package com.jarvis.nextgen;
import android.app.*;import android.content.*;import android.os.Build;
public final class ProactiveReceiver extends BroadcastReceiver {public static final String ACTION="com.jarvis.nextgen.PROACTIVE";private static final String CHANNEL="jarvis_proactive";
 public void onReceive(Context c,Intent i){ProactiveEngine e=new ProactiveEngine(c);if(!e.enabled())return;String type=i.getStringExtra("type");String text="MORNING".equals(type)?e.morningBriefing():e.upcoming();if(text==null)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CHANNEL,"JARVIS Proactive",NotificationManager.IMPORTANCE_DEFAULT));Intent open=c.getPackageManager().getLaunchIntentForPackage(c.getPackageName());PendingIntent pi=open==null?null:PendingIntent.getActivity(c,900,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("JARVIS").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setAutoCancel(true);if(pi!=null)b.setContentIntent(pi);nm.notify("MORNING".equals(type)?81001:81002,b.build());}
}
